async function pixCharge(){try{const rows=await req('/rest/v1/rpc/ba2_pix_meu',{method:'POST',body:{},auth:true}),x=Array.isArray(rows)?rows[0]:rows;if(!x?.chave_pix)throw Error('Cadastre sua chave Pix primeiro.');const amount=Number(document.querySelector('[name=valor]')?.value||0);if(!(amount>0))throw Error('Informe o valor da cobrança.');const code=pixPayload(x.chave_pix,x.nome_recebedor,x.cidade_recebedor,amount),box=document.getElementById('pixCharge');box.innerHTML=`<div class="card" style="margin-top:14px"><h2>QR Code Pix</h2><div id="pixQr" style="background:#fff;padding:14px;border-radius:12px;width:max-content;max-width:100%;margin:12px auto"></div><p style="text-align:center"><strong>${money(amount)}</strong></p><label>Pix Copia e Cola</label><textarea id="pixCode" rows="6" readonly>${esc(code)}</textarea><button class="btn secondary" onclick="BA.copyPix()">📋 Copiar Pix</button><p class="hint">O valor vai diretamente para a chave Pix cadastrada neste perfil. A confirmação do pagamento não é automática.</p></div>`;try{await loadQrLib();const q=document.getElementById('pixQr');q.innerHTML='';new QRCode(q,{text:code,width:220,height:220,correctLevel:QRCode.CorrectLevel.M})}catch(qe){document.getElementById('pixQr').innerHTML='<p style="color:#111">QR Code indisponível. Use o Pix Copia e Cola abaixo.</p>'}}catch(e){alert(e.message)}}
const proNav=()=>`<div class="nav"><button onclick="BA.professional()">✂ Meu painel</button><button onclick="BA.proProfile()">👤 Meu perfil</button><button onclick="BA.pix('professional')">💠 Meu Pix</button><button onclick="BA.logout()">Sair</button></div>`;
async function professionalPage(){current='professional';shop=null;try{
 const rows=await req('/rest/v1/rpc/ba2_meu_perfil_profissional',{method:'POST',body:{},auth:true});professional=Array.isArray(rows)?rows[0]:rows;if(!professional?.id)throw Error('Perfil profissional não vinculado.');
 const data=await req('/rest/v1/rpc/ba2_profissional_painel',{method:'POST',body:{},auth:true});
 const appts=Array.isArray(data?.agendamentos)?data.agendamentos:[],cash=Array.isArray(data?.recebimentos)?data.recebimentos:[];
 const total=cash.reduce((a,x)=>a+Number(x.valor||0),0);
 const apptHtml=appts.length?appts.map(a=>`<div class="item"><strong>${esc(localDate(a.inicio))}</strong> — ${esc(a.cliente_nome||'Cliente')}<p class="hint">${esc(a.servico_nome||'Serviço')} • ${esc(a.status)}</p>${['marcado','concluido'].includes(a.status)&&!a.recebido?`<button class="btn" onclick="BA.professionalReceive('${a.id}')">💰 ${a.status==='marcado'?'Concluir e receber':'Receber'}</button>`:a.recebido?'<p class="hint">✅ Recebimento já registrado</p>':''}</div>`).join(''):'<p class="muted">Nenhum atendimento encontrado.</p>';
 const cashHtml=cash.length?cash.map(x=>`<div class="item"><strong>${money(x.valor)}</strong><p class="hint">${esc(localDate(x.data_movimento))} • ${esc(x.forma_pagamento||'')}</p></div>`).join(''):'<p class="muted">Nenhum recebimento neste mês.</p>';
 shell(`<h1>✂ Olá, ${esc(professional.nome)}</h1><div class="card"><h2>${esc(professional.barbearia)}</h2><p class="muted">Seu painel individual. Você vê somente seus atendimentos e seus recebimentos.</p></div><div class="grid"><div class="card"><div class="muted">Meus recebimentos no mês</div><div class="stat">${money(total)}</div></div><div class="card"><div class="muted">Atendimentos exibidos</div><div class="stat">${appts.length}</div></div></div><div class="card"><h2>📅 Minha agenda</h2>${apptHtml}</div><div class="card"><h2>💰 Meu financeiro</h2>${cashHtml}</div><div class="card"><h2>💠 Pix individual</h2><p>Sua chave pertence somente ao seu perfil. O dono da barbearia não pode alterá-la.</p><div class="inline"><button class="btn secondary" onclick="BA.pix('professional')">⚙️ Configurar Pix</button><button class="btn" onclick="BA.pixChargePage('professional')">📱 Gerar QR Code</button></div></div>`,proNav())
 }catch(e){shell(`<h1>Painel profissional</h1><div class="alert">${esc(e.message)}</div>`,proNav())}}
async function masterPix(id){if(!isMaster)return;try{const rows=await req('/rest/v1/rpc/ba2_master_pix',{method:'POST',body:{p_barbearia:id},auth:true});shell(`<h1>👁 Chaves Pix</h1><p class="muted">Consulta somente. O Master não pode alterar ou excluir estas chaves.</p><div class="card">${rows.length?rows.map(x=>`<div class="item"><strong>${esc(x.profissional)}</strong> • ${esc(x.perfil)}<p class="hint">Chave: ${esc(x.chave_pix)}<br>Recebedor: ${esc(x.nome_recebedor)} • ${esc(x.cidade_recebedor)}</p></div>`).join(''):'<p class="muted">Nenhuma chave Pix cadastrada.</p>'}</div><button class="btn secondary" onclick="BA.master()">Voltar</button>`,masterNav())}catch(e){alert(e.message)}}

